repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('rovers', 14), ('city', 51), ('city', 6), ('city', 39), ('united', 32), ('city', 54)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.tagged.py:
"""Labels for the goals of fixtures."""


def labelled_goalss(fixtures, labels):
    """Pair each fixture's goals with its label, in order. fixtures beyond the end of `labels` get the label 'unlabelled'."""
    return [(labels[i], fixtures[i].goals) for i in range(len(labels))]


def label_width(labels):
    """Return the length of the longest label, or 0 when there are none."""
    return max((len(text) for text in labels), default=0)
